{"content":"import os, re, json

pages_dir = "/root/website-redesign"
html_files = sorted([f for f in os.listdir(pages_dir) if f.endswith(".html")])

print(f"Scanning {len(html_files)} HTML pages for JSON-LD quality...\n")

all_ok = True

for fname in html_files:
    fpath = os.path.join(pages_dir, fname)
    with open(fpath) as fh:
        html = fh.read()

    blocks = re.findall(r'<script type="application/ld\+json">(.*?)</script>', html, re.DOTALL)

    print(f"========== {fname} ({len(blocks)} JSON-LD block(s)) ==========")

    if not blocks:
        print("  *** MISSING JSON-LD ***\n")
        all_ok = False
        continue

    for i, raw in enumerate(blocks):
        raw = raw.strip()
        try:
            d = json.loads(raw)
        except json.JSONDecodeError as e:
            print(f"  Block {i+1}: INVALID JSON — {e}\n")
            all_ok = False
            continue

        # Resolve schema type
        if isinstance(d, list):
            # @graph
            items = d
            schema_types = []
            for item in items:
                if isinstance(item, dict):
                    schema_types.append(item.get('@type', 'UNKNOWN'))
            schema_type_str = " | ".join(schema_types) if schema_types else "UNKNOWN"
            print(f"  Block {i+1}: @graph ({len(items)} items) — types: {schema_type_str}")
            print(f"    Top-level keys: {list(d[0].keys()) if d else '[]'}")
            if '@context' not in (d[0] if d else {}):
                print("    *** @context missing in first graph item")
                all_ok = False
        elif isinstance(d, dict):
            schema_type = d.get('@type', 'MISSING')
            keys = list(d.keys())
            print(f"  Block {i+1}: @type={schema_type}, keys={keys[:10]}{'...' if len(keys)>10 else ''}")
            if '@context' not in d:
                print("    *** MISSING @context")
                all_ok = False
            if '@type' not in d:
                print("    *** MISSING @type")
                all_ok = False

            # Spot-check common required fields per type
            if schema_type == "WebSite":
                for field in ["url", "name"]:
                    if field not in d:
                        print(f"    *** WebSite missing '{field}'")
                        all_ok = False
            elif schema_type == "Organization":
                for field in ["name", "url"]:
                    if field not in d:
                        print(f"    *** Organization missing '{field}'")
                        all_ok = False
            elif schema_type == "Product" or schema_type == "Service":
                for field in ["name", "description"]:
                    if field not in d:
                        print(f"    *** {schema_type} missing '{field}'")
                        all_ok = False
        else:
            print(f"  Block {i+1}: UNKNOWN STRUCTURE (not dict/list) — {type(d)}")
            all_ok = False

    print()

print("=" * 60)
print(f"RESULT: {'ALL OK' if all_ok else 'ISSUES FOUND'}")
